window.kbPageData["views/entry/k-cda66bb8a91bd549"] = {"key":"entry/k-cda66bb8a91bd549","state":{"route":"entry/k-cda66bb8a91bd549"},"node":{"id":"k-cda66bb8a91bd549","mode":"k","title":"公开审理原则及其例外","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["审判原则上公开，法定情形可以或应当不公开"],"qs":["江苏 2025 B类 行测#16"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"人民法院审理案件原则上应当公开。法律规定应当不公开审理的，法院应适用相应例外。法律允许依申请不公开审理的，法院可以在当事人提出申请后依法决定。","review":{"definition":"人民法院审理案件原则上应当公开。法律规定应当不公开审理的，法院应适用相应例外。法律允许依申请不公开审理的，法院可以在当事人提出申请后依法决定。","explanation":"第16题D项的“一律公开”忽略了法定例外。以民事案件为例，涉及国家秘密、个人隐私的案件不公开审理，离婚案件或涉及商业秘密的案件经当事人申请可以不公开审理。","references":[],"evidence":"离婚案件，涉及商业秘密的案件，当事人申请不公开审理的，可以不公开审理。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#16":{"paper":"江苏 2025 B类 行测","n":16,"mod":"常识判断","src":["91e0d9fd02ca7ec6d61f.pdf",4],"asrc":["f2ff67a0f2a2f7e8e926.pdf",6],"card":"e4d47d034c952b8ddf91e4bf","links":[{"id":"k-cda66bb8a91bd549","role":"解题依据","why":"法律对公开审理规定了例外，据此可判断公开要求的适用范围。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-cda66bb8a91bd549":[["江苏 2025 B类 行测#16"]]}};
